def rearange_string(s):
    # Count occurrences of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if any character has more than 2 occurrences
    for count in char_count.values():
        if count > 2:
            return False

    # Try to arrange the string
    sorted_chars = sorted(char_count.items(), key=lambda x: x[1], reverse=True)

    result = []
    i, j = 0, len(sorted_chars) - 1

    while i <= j:
        if i == j:
            result.append(sorted_chars[i][0])
        else:
            result.extend([sorted_chars[i][0], sorted_chars[j][0]])
        i += 1
        j -= 1

    return ''.join(result)
