def max_sub_array_sum_repeated(arr, n, k):
    # Calculate the maximum subarray sum for the original array
    max_sum = float('-inf')
    current_sum = 0

    for num in arr:
        current_sum += num
        if current_sum > max_sum:
            max_sum = current_sum

    # If all elements are negative, return the maximum element
    if max_sum < 0:
        return max(arr)

    # Calculate the total sum of the repeated array
    total_sum = n * max_sum

    # Calculate the sum of the first k-1 repetitions
    first_k_sum = 0
    for i in range(k-1):
        first_k_sum += sum(arr)

    # Return the maximum of the total sum and the sum of the first k-1 repetitions
    return max(total_sum, first_k_sum)
